files.content:
// The report a finished ask hands its caller (an agent's owner).
//
// A turn's `content` is what the live view still needs at its end: the text
// since the last tool batch. An answer the turn kept going past (a todo
// reminder or queued input arrived after it) and a turn that queued input
// followed in the same ask are both older than that, so the result carries
// them in `reportContent`, ahead of the newest text.

export function joinReports(parts) {
  return parts
    .map((part) => String(part || '').trim())
    .filter(Boolean)
    .join('\n\n');
}

/** The whole report of a result: `reportContent` when the ask carried earlier
 *  answers, else its content. */
export function turnReportText(result) {
  if (typeof result?.reportContent === 'string') return result.reportContent;
  return typeof result?.content === 'string' ? result.content : '';
}

/** `result` with `earlier` answers ahead of its own report. */
export function withEarlierReport(result, earlier) {
  if (!earlier) return result;
  return { ...result, reportContent: joinReports([earlier, turnReportText(result)]) };
}

/** A turn that fails after such answers still hands them on: `error` carries
 *  them (`carriedReport`, earliest first) to whoever reports the failure. */
export function carryReportOnError(error, earlier) {
  if (!earlier || !error || typeof error !== 'object') return error;
  error.carriedReport = joinReports([earlier, typeof error.carriedReport === 'string' ? error.carriedReport : '']);
  return error;
}

// manager/turn-durability.mjs
// One unsettled turn per session. A finished (or failed) turn stays
// unsettled — its checkpoint kept — until a landed save of its session
// carries the turn's coverage token (store/transcript-durability.mjs); only
// that acknowledgement deletes the checkpoint. The next turn of the session
// waits for it before it opens its own checkpoint or touches the session, and
// a save that cannot land blocks that turn with a TurnPersistenceError
// instead of releasing it. A settled promise, an idle queue or a coalesced,
// cancelled or dropped write is never an acknowledgement. Sessions are
// independent: nothing here waits on another session's saves.
import { saveSessionAsync } from '../store.mjs';
import { landedTranscript, landedTranscriptMatches, mintTranscriptEpoch } from '../store/transcript-durability.mjs';
import { clearTurnCheckpoint } from './turn-checkpoint.mjs';

const _unsettled = new Map(); // sessionId → { session, turnToken, generation, ack, error }

export class TurnPersistenceError extends Error {
  constructor(sessionId, message, cause = null) {
    super(`Session ${sessionId}: ${message}${cause ? ` (${cause.message || cause})` : ''}`);
    this.name = 'TurnPersistenceError';
    this.code = 'ETURNNOTDURABLE';
    this.sessionId = sessionId;
    if (cause) this.cause = cause;
  }
}

/** Whether a landed save of `session` carries `turnToken`'s coverage. */
export function turnCoveredOnDisk(session, turnToken) {
  return landedTranscript(session)?.coverage === turnToken;
}

function release(sessionId, entry) {
  if (_unsettled.get(sessionId) !== entry) return;
  _unsettled.delete(sessionId);
  clearTurnCheckpoint(sessionId, entry.turnToken);
}

/** Keep `turnToken` (already the session's `turnCoverage`) unsettled until a
 *  landed save covers it; `save` is the save expected to. Resolves whether
 *  it did. */
export function holdTurnUntilDurable({ sessionId, session, turnToken, generation, save }) {
  const entry = { session, turnToken, generation, error: null, ack: null };
  _unsettled.set(sessionId, entry);
  entry.ack = Promise.resolve(save)
    .then(
      () => turnCoveredOnDisk(session, turnToken),
      (error) => {
        entry.error = error;
        return false;
      }
    )
    .then((covered) => {
      if (covered) release(sessionId, entry);
      return covered;
    });
  return entry.ack;
}

/** Whether this process holds a turn of `sessionId` not yet durable. */
export function hasUnsettledTurn(sessionId) {
  return _unsettled.has(sessionId);
}

/** A closed or deleted session: nothing will open on it again. */
export function forgetUnsettledTurn(sessionId) {
  _unsettled.delete(sessionId);
}

/** Resolves once the previous turn of `sessionId` is durably covered (its
 *  checkpoint then deleted). When its own save did not land it, one fresh
 *  save of the finalized transcript is attempted; if that does not land
 *  either, throws TurnPersistenceError and the checkpoint stays. */
export async function awaitPreviousTurnDurable(sessionId) {
  const entry = _unsettled.get(sessionId);
  if (!entry || (await entry.ack)) return;
  try {
    await saveSessionAsync(entry.session, { expectedGeneration: entry.generation });
  } catch (error) {
    entry.error = error;
  }
  if (!turnCoveredOnDisk(entry.session, entry.turnToken)) {
    throw new TurnPersistenceError(
      sessionId,
      'the previous turn is not saved to disk, so the next turn cannot start',
      entry.error
    );
  }
  release(sessionId, entry);
}

/** Make `session`'s current transcript durable, so a turn opening on it
 *  names a base that is on disk. A transcript that is not a pure extension
 *  of the last landed one (an unsaved rewrite) starts a new epoch first. */
export async function ensureDurableTranscript(session) {
  if (landedTranscriptMatches(session)) return;
  const landed = landedTranscript(session);
  const messages = Array.isArray(session.messages) ? session.messages : [];
  const extendsLanded =
    landed &&
    landed.epoch === session.transcriptEpoch &&
    landed.refs.length <= messages.length &&
    landed.refs.every((message, index) => message === messages[index]);
  if (typeof session.transcriptEpoch !== 'string' || (landed && !extendsLanded)) {
    session.transcriptEpoch = mintTranscriptEpoch();
  }
  let failure = null;
  try {
    await saveSessionAsync(session, { expectedGeneration: session.generation });
  } catch (error) {
    failure = error;
  }
  if (!landedTranscriptMatches(session)) {
    throw new TurnPersistenceError(session.id, 'the conversation is not saved to disk, so the next turn cannot start', failure);
  }
}

// store/transcript-durability.mjs
// What a session's canonical record durably holds, as evidence for the turn
// checkpoints (manager/turn-checkpoint.mjs) — never inferred from in-memory
// freshness.
//
//   transcriptEpoch  persisted. Names one append-only lineage of the
//                    transcript: a record of epoch E with `length` messages
//                    agrees with every other record of E on their common
//                    prefix. A history rewrite (compaction, a prefix edit,
//                    a recovery splice) mints a new epoch.
//   turnCoverage     persisted. The token of the last turn whose finalized
//                    transcript this record carries, so a checkpoint the
//                    record already covers is deleted, never replayed.
//
// A landed save records, per session object, the exact epoch, coverage and
// message references it serialized (captured when the bytes were built, so a
// coalesced or later-built write reports what it actually wrote). Only that
// record proves what is on disk; a settled promise or an idle queue does not.
import { randomUUID } from 'node:crypto';
import { basename, dirname } from 'node:path';
import { sessionPath } from './session-paths.mjs';
import { _storedSessionFromFile, STORED_SESSION_UNREADABLE } from './serialize.mjs';

const _landed = new WeakMap(); // session → { epoch, coverage, refs, saveEpoch }
const _snapshotHooks = new WeakMap(); // session → () => void

export function mintTranscriptEpoch() {
  return randomUUID();
}

/** Run `hook` before every serialization of `session` (the turn checkpoint
 *  journals a history rewrite, under a new epoch, before any record carries
 *  it). Returns the unregister function. */
export function setTranscriptSnapshotHook(session, hook) {
  _snapshotHooks.set(session, hook);
  return () => {
    if (_snapshotHooks.get(session) === hook) _snapshotHooks.delete(session);
  };
}

/** The transcript identity a save of `session` is about to serialize. */
export function captureTranscriptSnapshot(session) {
  _snapshotHooks.get(session)?.();
  return {
    epoch: typeof session.transcriptEpoch === 'string' ? session.transcriptEpoch : null,
    coverage: typeof session.turnCoverage === 'string' ? session.turnCoverage : null,
    refs: Array.isArray(session.messages) ? session.messages.slice() : [],
  };
}

/** A save of `snapshot` (issued under `saveEpoch`) landed on disk. */
export function recordLandedTranscript(session, snapshot, saveEpoch) {
  if (!session || !snapshot) return;
  const current = _landed.get(session);
  const issued = Number.isFinite(saveEpoch) ? saveEpoch : 0;
  if (current && current.saveEpoch > issued) return;
  _landed.set(session, { ...snapshot, saveEpoch: issued });
}

export function landedTranscript(session) {
  return (session && _landed.get(session)) || null;
}

/** Whether the last landed save of `session` holds exactly its transcript. */
export function landedTranscriptMatches(session) {
  const landed = landedTranscript(session);
  const messages = Array.isArray(session?.messages) ? session.messages : null;
  if (!landed || !messages || landed.epoch !== session.transcriptEpoch) return false;
  if (landed.refs.length !== messages.length) return false;
  return landed.refs.every((message, index) => message === messages[index]);
}

/** The durable transcript a turn opening now would be taken against
 *  (`{ epoch, refs }`), or null when no landed save holds `session`'s
 *  current transcript exactly. */
export function durableTranscriptBase(session) {
  if (!landedTranscriptMatches(session)) return null;
  const landed = landedTranscript(session);
  return { epoch: landed.epoch, refs: landed.refs };
}

/** The canonical record of `id` as it is on disk (never a cached or live
 *  copy), or null when it is absent, unreadable or not this session's. */
export function readDurableSessionRecord(id) {
  const path = sessionPath(id);
  const record = _storedSessionFromFile(dirname(path), basename(path));
  return record && record !== STORED_SESSION_UNREADABLE ? record : null;
}

// How long a running shell job has gone without writing to stdout or stderr.
// Silence is read from the capture files' mtime (the writer is the child, so
// nothing has to poll), floored at the job's start. It is a warning only:
// builds and installs can be legitimately quiet, so nothing is ever killed
// from here, and any output at all resets the clock.
import { statSync } from 'node:fs';
import { formatDuration } from '../../../../../shared/time-format.mjs';
import { getBackgroundTask } from '../../../../../shared/background-tasks.mjs';
import { STALL_ABORT_S, resolveTimeoutMs } from '../../../stall-policy.mjs';

// Defaults to the agent stall budget (600 s): a quiet job past the point where
// a silent model turn would be reaped is worth a look.
export const SHELL_OUTPUT_SILENCE_WARN_MS = resolveTimeoutMs('MIXDOG_SHELL_OUTPUT_SILENCE_WARN_MS', STALL_ABORT_S * 1000);

/** Milliseconds since the job last wrote to stdout/stderr (or started), or null
 *  when silence is unknown. The spawner creates both capture files before the
 *  command runs (mixdog-spawn open_capture_files, or the paired spill open), so
 *  a stream whose file cannot be stat'd (even ENOENT) is unknown, not quiet:
 *  its recent output could be what we cannot see. `task` is the background
 *  task; the stream paths come from `result` or the task meta. */
export function shellOutputSilenceMs(task, { now = Date.now(), result = task?.result } = {}) {
  let last = null;
  for (const path of [result?.stdout_path || task?.meta?.stdout, result?.stderr_path || task?.meta?.stderr]) {
    if (!path) continue;
    try {
      last = Math.max(last ?? 0, statSync(path).mtimeMs);
    } catch {
      return null;
    }
  }
  if (last == null) return null;
  return Math.max(0, now - Math.max(last, Number(task?.startedAtMs) || 0));
}

/** The warning text for a silence at or past the threshold, else null. */
export function describeShellOutputSilence(silentMs, warnMs = SHELL_OUTPUT_SILENCE_WARN_MS) {
  if (!(silentMs >= warnMs)) return null;
  return `no output for ${formatDuration(silentMs, { mostSignificantOnly: true })} — may be hung; inspect or cancel`;
}

/** The warning for one running shell task, else null. */
export function shellTaskSilenceNote(task, { now = Date.now(), warnMs = SHELL_OUTPUT_SILENCE_WARN_MS, result } = {}) {
  if (task?.surface !== 'shell' || task.status !== 'running') return null;
  return describeShellOutputSilence(shellOutputSilenceMs(task, { now, result: result ?? task.result }), warnMs);
}

/** The quietest of the running shell jobs an agent's `task wait` is parked on:
 *  `{ taskId, silentMs, hung }`, or null when it waits on none. */
export function waitedJobSilence(taskIds, { now = Date.now(), warnMs = SHELL_OUTPUT_SILENCE_WARN_MS } = {}) {
  let worst = null;
  for (const taskId of taskIds || []) {
    const task = getBackgroundTask(taskId);
    if (task?.surface !== 'shell' || task.status !== 'running') continue;
    const silentMs = shellOutputSilenceMs(task, { now });
    if (silentMs != null && (!worst || silentMs > worst.silentMs)) worst = { taskId, silentMs, hung: silentMs >= warnMs };
  }
  return worst;
}
